import csv
import os
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..','exemplar_rewrites.csv')
C={}  # ref -> (v1_title, v2_title, v2_definition, span_note)
R=[]  # (ref, level, indicator, method, notes)
def comp(ref,v1,v2,d): C[ref]=(v1,v2,d)
def ind(ref,lvl,text,method,notes): R.append((ref,lvl,text,method,notes))

comp('1.3.4','Forest health assessment','Assess forest health conditions and recommend responses',
 'Detects, diagnoses and documents biotic and abiotic stressors affecting forest stands, and recommends monitoring or management responses proportionate to severity, spread risk and management objectives. Span L1-L4.')
ind('1.3.4','L1','Records presence, symptoms and severity of forest pests, diseases and abiotic damage on survey plots using the program damage codes, so that records pass QA review.','observation|task-book: qualified evaluator observes plot work; record audit against a check-cruise','mode=unaided (field diagnosis is formation-critical; v1 T1 tagged H/Hi/P); use=select|develop; attribute=autonomy (supervised); replaces v1 F I1,I3,I5 and K "Recognizes common forest pests" ; obs4=3')
ind('1.3.4','L1','Collects and labels symptomatic tissue or insect samples for laboratory identification following the program chain-of-custody and handling procedure.','observation|record: sample submission audit (lab acceptance rate)','mode=unaided; use=select|develop; replaces v1 F I2; obs4=3')
ind('1.3.4','L2','Identifies the causal agent of common forest health problems in the field to the level the program requires, distinguishing biotic from abiotic causes and citing the diagnostic signs used.','work-product|interview: field identification exercise at known sites or with reference specimens; oral questioning on signs used','mode=unaided; use=select; replaces v1 I K "Diagnoses forest health problems; understands pest ecology" (compound) and I I1; obs4=3')
ind('1.3.4','L2','Conducts a systematic forest health survey of an assigned area and reports the extent and severity of damage with mapped locations and stated sampling limitations.','work-product: survey report scored with a rubric (coverage, accuracy vs. check plots, limitations stated)','mode=assisted (remote-sensing or GIS layers permitted; ground verification required); use=select|develop; replaces v1 I I2,I3; obs4=3')
ind('1.3.4','L3','Diagnoses a forest health problem with atypical symptoms or multiple interacting causes, documenting the evidence considered, the alternative diagnoses rejected, and whether laboratory confirmation is needed.','simulation|interview: real case file plus structured interview scored with BARS','mode=assisted; use=select|promote; attribute=complexity (non-routine, conflicting evidence); replaces v1 A I1 "Diagnoses complex forest health problems" (adjective-only gradation); obs4=3')
ind('1.3.4','L3','Recommends a response to a detected outbreak (monitor, treat, salvage or no action) for a stand or project area, with a rationale linking severity, spread risk, objectives and cost.','work-product: recommendation memo scored by SME panel','mode=assisted; use=promote|develop; v1 T3; obs4=3')
ind('1.3.4','L4','Develops a forest health detection and response plan for an administrative unit or ownership, specifying survey methods, detection thresholds, response triggers and responsible parties.','work-product|interview: plan reviewed by external SME panel; structured interview on design choices','mode=assisted; use=promote; replaces v1 A "Leads forest health programs" (O flag) and E "Leads major forest health initiatives" (O); obs4=3')
ind('1.3.4','L4','Sets the ground-verification sample and accuracy acceptance criteria for AI- or remote-sensing-generated forest damage maps before they are used in program decisions.','work-product|interview: acceptance-criteria document; defense in structured interview','mode=supervisory; use=promote; attribute=augmented practice; new (no v1 equivalent); obs4=3')

comp('4.1.2','Wildlife observation and sign interpretation (merge with 1.4.2 Wildlife survey techniques)','Detect, identify and record wildlife presence and activity',
 'Detects and identifies wildlife and wildlife sign using direct observation, indirect evidence and remote detection devices, and records observations to protocol so that data support population and habitat inferences. Span L1-L3; survey and monitoring design moves to a separate analytical competency.')
ind('4.1.2','L1','Records detections on a standardized datasheet or device under a qualified observer\'s direction, so that species codes, counts, locations and effort fields pass the program QA check.','observation|record: data audit of field records','mode=unaided (device entry permitted); use=select|develop; attribute=autonomy; merges v1 4.1.2 F I4 and 1.4.2 F I4 (near-duplicate competencies, which weakens discriminant validity); obs4=3')
ind('4.1.2','L1','Deploys and services camera traps or acoustic recorders to the protocol placement, settings and maintenance schedule, documenting each deployment.','observation|task-book: deployment checked by evaluator; deployment-log audit','mode=unaided; use=select|develop; v1 4.1.2 F I6, 1.4.2 T1; obs4=3')
ind('4.1.2','L2','Identifies common regional species by sight, sound and sign (tracks, scat, nests, feeding sign) at or above the program observer-certification accuracy threshold.','knowledge-test|work-product: identification test with known answers (field, audio or photo set)','mode=unaided (formation-critical; v1 T2 tagged H/Hi/P); use=select; replaces v1 I K "Proficient in wildlife identification" (level label as content); obs4=3')
ind('4.1.2','L2','Reviews automated species classifications from camera or acoustic data, verifying all low-confidence detections and a random sample of high-confidence ones, and records accepted, corrected and rejected detections.','simulation|record: seeded-error dataset (score = errors caught, false alarms); review log audit','mode=assisted; use=select|develop; attribute=augmented practice; replaces v1 I I5 "Manages camera trap data and uses AI identification tools" (compound, tool-locked); obs4=3')
ind('4.1.2','L3','Adapts the survey protocol when site conditions prevent standard execution, documenting the deviation and its likely effect on detectability and comparability.','simulation|interview: case scenario plus structured interview scored with BARS','mode=assisted; use=promote; attribute=guidelines (adapting rather than following) and complexity; obs4=3')
ind('4.1.2','L3','Evaluates a trainee\'s identification and recording performance against the program certification standard and documents an entrustment decision.','observation|record: observed evaluation; agreement with a second evaluator on the same trainee','mode=unaided; use=develop|promote; attribute=formation of others (task-book evaluator; see IO-C01); obs4=3')

comp('2.2.2','Statistical analysis and interpretation','Analyze environmental data statistically and interpret results for decisions',
 'Selects, applies and interprets statistical methods appropriate to the data, design and decision question, states assumptions and uncertainty, and communicates what the results do and do not support. Span L1-L4.')
ind('2.2.2','L1','Calculates descriptive statistics and a two-group comparison for a monitoring dataset, stating the test assumptions and whether the data meet them, for review by an analyst.','work-product|knowledge-test: timed dataset task; short knowledge test on enabling concepts','mode=assisted (software and code assistants allowed; outputs must be checked); use=select|develop; replaces v1 F K "Understands basic statistics" (B1) and I1,I3; obs4=3')
ind('2.2.2','L1','Produces graphs that show distribution, central tendency and uncertainty for a dataset without misleading scales, following the program style guide.','work-product: graphics scored with a checklist','mode=assisted; use=select|develop; v1 F I2, T3 (tagged Ac/Lo/P: AI compresses this; keep human check of misleading displays); obs4=3')
ind('2.2.2','L2','Selects and fits a regression or ANOVA-family model appropriate to the design and response type, checks diagnostics, and reports effect sizes with confidence intervals.','work-product: analysis task with scoring rubric; code review','mode=assisted; use=select; replaces v1 I I1,I3,I4 and K "Applies diverse statistical methods appropriately"; obs4=3')
ind('2.2.2','L2','Verifies an AI-generated or automated analysis script against the analysis plan by re-running key steps and checking data handling, model specification and outputs, recording each discrepancy found.','simulation: seeded-error script (score = discrepancies found)','mode=assisted; use=select|develop; attribute=augmented practice; new; obs4=3')
ind('2.2.2','L3','Analyzes data with hierarchical structure, autocorrelation or imperfect detection using an appropriate model, and explains to a non-specialist decision-maker what the results do and do not support.','work-product|interview: analysis task plus explain-back interview scored with BARS','mode=assisted; use=promote; attribute=complexity; replaces v1 A I1,I5 (method lists) ; obs4=3')
ind('2.2.2','L3','Reviews a colleague\'s statistical analysis for a decision document and returns written findings on design, assumption and interpretation errors.','work-product: review memo on a seeded case','mode=assisted; use=promote|develop; attribute=scope and formation; obs4=3')
ind('2.2.2','L4','Sets statistical acceptance criteria (power, effect size, error rates) for a monitoring program and documents their basis so that an external reviewer can reproduce the design decision.','work-product|interview: design document reviewed by external panel; structured interview','mode=assisted; use=promote; replaces v1 E "Shapes statistical practice in environmental field" (B3, code 0) and "Leads major statistical programs" (O); obs4=3')

comp('2.1.3','GPS data collection and management','Capture and quality-assure positional field data',
 'Collects, corrects and quality-assures positional data for field features to the accuracy their intended use requires, and documents accuracy and metadata so that data can be integrated and trusted. Span L1-L3. Receiver models and correction services move to the tool layer; geodetic control (v1 A I2) belongs to a surveying specialist competency.')
ind('2.1.3','L1','Records point, line and polygon features with a GNSS receiver or mobile device using the project coordinate system and attribute schema, so that records pass a completeness check.','observation|record: field check; data completeness audit','mode=assisted; use=select|develop; replaces v1 F I1 "Uses handheld GPS to record waypoints" (T flag) and I3,I4; obs4=3')
ind('2.1.3','L1','Checks recorded positions against a known control point or reference layer before leaving a site and re-collects any that exceed the project tolerance.','observation|record: field observation; QA log','mode=assisted; use=select|develop; new (adds a standard missing in v1); obs4=3')
ind('2.1.3','L2','Selects the positioning method (consumer GNSS, corrected GNSS, offsets or map digitizing) that meets the accuracy the data use requires, and records expected accuracy in the metadata.','sjt|work-product: scenario items; metadata audit','mode=assisted; use=select; attribute=guidelines (selects among methods); replaces v1 I I2 "Uses GPS with sub-meter accuracy (DGPS, RTK)" (T flag); obs4=3')
ind('2.1.3','L2','Post-processes or corrects field positions and delivers a dataset with metadata that meets the organization geospatial data standard for GIS integration.','work-product: delivered dataset checked against the standard','mode=assisted (v1 T2 tagged Ac/Lo/P: automated pipelines compress this; verification stays human); use=select; obs4=3')
ind('2.1.3','L3','Designs a field positioning protocol for a project, specifying accuracy targets, equipment class, control checks and QA steps, and trains crews to apply it.','work-product|observation: protocol document; observed crew training','mode=assisted; use=promote|develop; attribute=formation; replaces v1 I I1 and A I5; obs4=3')

comp('3.1.4','Contract and agreement administration','Administer contracts and agreements for environmental work',
 'Prepares, monitors and closes out contracts, grants, cooperative and partnership agreements so that deliverables, payments and modifications comply with the instrument terms and applicable procurement and financial-assistance requirements. Span L1-L4. Jurisdiction-variable; federal COR certification and state equivalents are qualification gates, not indicators.')
ind('3.1.4','L1','Maintains the official file for an assigned contract or agreement so that every deliverable, invoice, modification and communication is recorded and retrievable for audit.','record: file audit against the program file checklist','mode=assisted; use=select|develop; replaces v1 F I1 and K "Understands contract basics" (B1); obs4=3')
ind('3.1.4','L1','Checks invoices against the instrument payment terms and accepted deliverables and routes each discrepancy to the responsible official before approval.','simulation: invoice set with seeded discrepancies','mode=assisted (v1 T2 tagged Ac/Lo/C: automated matching compresses this; the routing decision stays human); use=select; obs4=3')
ind('3.1.4','L2','Drafts a statement of work with measurable deliverables, acceptance criteria and schedule that a contracting or grants officer accepts without substantive revision.','work-product: SOW scored with contracting SME rubric','mode=assisted (LLM drafting allowed; candidate verifies terms against the requirement); use=select; replaces v1 I I1 "Drafts scopes of work" (no standard); obs4=3')
ind('3.1.4','L2','Documents contractor or partner performance against acceptance criteria and starts the instrument corrective process when deliverables fall short.','simulation|record: case exercise; performance file audit','mode=assisted; use=select; replaces v1 I I3 "Manages contractor performance" and I4 "Ensures contract compliance" (B5); obs4=3')
ind('3.1.4','L3','Resolves a non-routine contract or agreement issue (scope change, performance dispute, unanticipated site condition) by preparing the modification or corrective-action record and its justification for the authorized official.','simulation|interview: case exercise and structured interview scored with BARS','mode=assisted; use=promote; attribute=complexity; replaces v1 I I6 "Resolves contract issues" and A I5; obs4=3')
ind('3.1.4','L4','Develops standard scope, deliverable and acceptance templates for a program recurring instrument types, and confirms with the legal or contracting office that they meet applicable requirements.','work-product: templates plus review record','mode=assisted; use=promote; jurisdiction_variable=true; replaces v1 A I4 and E "Shapes contracting practice" (B3); obs4=3')

