ind('4.1.3','L1','Collects and preserves water samples with chain-of-custody documentation that passes laboratory acceptance on receipt.','observation|record: lab acceptance and rejection records','mode=unaided; use=select; replaces v1 F I2,I3; obs4=3')
ind('4.1.3','L2','Collects benthic macroinvertebrate or other biological samples to the program protocol so that duplicate samples meet the program precision criteria.','record|observation: QA duplicate results; field observation','mode=unaided; use=select; replaces v1 I I2 and T2; obs4=3')
